function prefersMarkdown(acceptHeader) {
  if (!acceptHeader) return false;
  const parts = acceptHeader.toLowerCase().split(',');
  let mdQ = -1;
  let htmlQ = -1;
  for (const raw of parts) {
    const segs = raw.trim().split(';');
    const mime = segs[0].trim();
    let q = 1;
    for (let i = 1; i < segs.length; i++) {
      const kv = segs[i].trim().split('=');
      if (kv[0] === 'q' && kv[1]) {
        const parsed = Number.parseFloat(kv[1]);
        if (!Number.isNaN(parsed)) q = parsed;
      }
    }
    if (mime === 'text/markdown' || mime === 'text/x-markdown') {
      if (q > mdQ) mdQ = q;
    } else if (mime === 'text/html' || mime === 'application/xhtml+xml') {
      if (q > htmlQ) htmlQ = q;
    }
  }
  return mdQ > 0 && mdQ >= htmlQ;
}

function normalizePath(pathname) {
  if (!pathname || pathname === '/') return '/';
  let p = pathname;
  if (p.length > 1 && p.endsWith('/')) p = p.slice(0, -1);
  if (p.endsWith('/index.html')) p = p.slice(0, -'/index.html'.length) || '/';
  else if (p.endsWith('.html')) p = p.slice(0, -'.html'.length) || '/';
  return p;
}

export default function middleware(request) {
  const url = new URL(request.url);
  const host = (request.headers.get('host') || url.host || '').toLowerCase();

  if (host === 'www.warisanarisan.com' || host.endsWith('.vercel.app')) {
    return Response.redirect('https://warisanarisan.com' + url.pathname + url.search, 308);
  }

  const accept = request.headers.get('accept') || '';
  if (prefersMarkdown(accept)) {
    const norm = normalizePath(url.pathname);
    const hit = MARKDOWN_ROUTES[norm];
    if (hit) {
      return new Response(hit, {
        status: 200,
        headers: {
          'Content-Type': 'text/markdown; charset=utf-8',
          'Vary': 'Accept',
          'Cache-Control': 'public, max-age=0, s-maxage=3600, stale-while-revalidate=86400',
          'X-Robots-Tag': 'index, follow',
        },
      });
    }

    const body404 = [
      '# 404 - Page Not Found | Warisan vs Arisan (warisanarisan.com)',
      '',
      'No Warisan vs Arisan page exists at `' + url.pathname + '`.',
      '',
      '## Official Entry Points',
      '- [AI Discovery Guide (/llms.txt)](https://warisanarisan.com/llms.txt)',
      '- [Full Reference (/llms-full.txt)](https://warisanarisan.com/llms-full.txt)',
      '- [Beranda (ID)](https://warisanarisan.com/)',
      '- [English Overview](https://warisanarisan.com/en)',
      '- [36-Dish Culinary Merge Guide](https://warisanarisan.com/panduan)',
      '- [XML Sitemap](https://warisanarisan.com/sitemap.xml)',
      '',
    ].join('\n');

    return new Response(body404, {
      status: 404,
      headers: {
        'Content-Type': 'text/markdown; charset=utf-8',
        'Vary': 'Accept',
        'Cache-Control': 'no-store',
      },
    });
  }

  return new Response(null, {
    headers: {
      'x-middleware-next': '1',
      'Vary': 'Accept',
    },
  });
}

